history.definition:
ADD CONSTRAINT exam_status_check CHECK (
  status IN ('draft', 'configured', 'ready', 'collecting', 'grading', 'reviewing', 'finalized', 'published', 'archived')
)

ADD CONSTRAINT ck_ai_grade_question_type CHECK (
  question_type IN (
    'single_choice', 'multiple_choice', 'true_false', 'fill_blank', 'numeric',
    'short_answer', 'calculation', 'essay', 'discussion'
  )
)

ADD CONSTRAINT ck_ai_grade_grader_type CHECK (
  grader_type IN ('rule_based_objective', 'mock_llm_subjective', 'llm_subjective')
)

constraints.definition:
CHECK (
    claim_expires_at IS NULL OR claimed_at IS NULL OR claim_expires_at > claimed_at
  )

history.definition:
ADD CONSTRAINT ck_review_task_grade_round CHECK (
  grade_round IN ('single', 'first_mark', 'second_mark', 'appeal_review')
)

ADD CONSTRAINT ck_final_grade_source CHECK (
  source IN ('double_mark_auto', 'arbitration', 'single_review', 'rule_auto')
)

ADD CONSTRAINT ck_final_grade_status CHECK (
  status IN ('calculating', 'pending_confirmation', 'confirmed', 'pending_publish', 'published', 'locked')
)

constraints.definition:
CHECK (
      auto_confirmed_count + human_confirmed_count + review_count + failed_count <= total_count
    )

history.definition:
ADD CONSTRAINT chk_grading_evaluation_slice_dimension CHECK (
    dimension IN ('subject','archetype','score_band','ocr_quality','answer_length','rubric_complexity','error_source')
  )
